/* =====================================================================
   Компьютерный анализ данных — образовательная платформа
   20 практических занятий по 2 часа (120 мин) по силлабусу НИУ КЭУ
   ===================================================================== */
'use strict';

/* ---------- Утилиты ---------- */
const $ = (s, el = document) => el.querySelector(s);
const $$ = (s, el = document) => [...el.querySelectorAll(s)];
const fmt = (n, d = 0) => Number(n).toLocaleString('ru-RU', { minimumFractionDigits: d, maximumFractionDigits: d });
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const store = {
  get(k, def) { try { const v = localStorage.getItem('kad_' + k); return v === null ? def : JSON.parse(v); } catch (e) { return def; } },
  set(k, v) { try { localStorage.setItem('kad_' + k, JSON.stringify(v)); } catch (e) { /* хранилище недоступно */ } }
};
function rng(seed) { return function () { seed |= 0; seed = seed + 0x6D2B79F5 | 0; let t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const pick = (r, arr) => arr[Math.floor(r() * arr.length)];
const between = (r, a, b) => a + Math.floor(r() * (b - a + 1));
const pad = n => String(n).padStart(2, '0');
const sum = a => a.reduce((s, x) => s + x, 0);
const mean = a => sum(a) / a.length;
const median = a => { const s = [...a].sort((x, y) => x - y), m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
const stdevS = a => { const m = mean(a); return Math.sqrt(sum(a.map(x => (x - m) ** 2)) / (a.length - 1)); };
const correl = (x, y) => { const mx = mean(x), my = mean(y); let sxy = 0, sxx = 0, syy = 0; x.forEach((v, i) => { sxy += (v - mx) * (y[i] - my); sxx += (v - mx) ** 2; syy += (y[i] - my) ** 2; }); return sxy / Math.sqrt(sxx * syy); };
const slope = (y, x) => { const mx = mean(x), my = mean(y); let a = 0, b = 0; x.forEach((v, i) => { a += (v - mx) * (y[i] - my); b += (v - mx) ** 2; }); return a / b; };
const intercept = (y, x) => mean(y) - slope(y, x) * mean(x);

/* =====================================================================
   УЧЕБНЫЕ НАБОРЫ ДАННЫХ (генерируются одинаково у всех студентов)
   ===================================================================== */
const DS = {};

/* 1. Продажи магазина электроники — 48 записей, январь–июнь 2026 */
(function () {
  const r = rng(2026);
  const P = [['Ноутбук', 'Техника', 52000, 1, 6], ['Смартфон', 'Техника', 24000, 1, 10], ['Монитор', 'Техника', 18500, 1, 8], ['Принтер', 'Оргтехника', 14200, 1, 5],
    ['Наушники', 'Аксессуары', 3500, 2, 20], ['Клавиатура', 'Аксессуары', 1600, 3, 25], ['Мышь', 'Аксессуары', 900, 5, 40], ['Бумага А4', 'Канцтовары', 450, 10, 60]];
  const REG = ['Бишкек', 'Ош', 'Чуйская обл.', 'Иссык-Кульская обл.', 'Нарынская обл.'];
  const MAN = ['Асанов Н.', 'Бекова А.', 'Касымов Т.', 'Осмонова Д.', 'Жумабаев Э.'];
  const rows = [];
  for (let i = 0; i < 48; i++) {
    const m = 1 + Math.floor(i / 8), d = between(r, 1, 28), p = pick(r, P);
    rows.push([i + 1, `${pad(d)}.${pad(m)}.2026`, pick(r, REG), pick(r, MAN), p[0], p[1], between(r, p[3], p[4]), p[2]]);
  }
  rows.sort((a, b) => { const [da, ma] = a[1].split('.'), [db, mb] = b[1].split('.'); return (ma - mb) || (da - db); });
  rows.forEach((row, i) => row[0] = i + 1);
  DS.sales = { name: 'Продажи', title: 'Продажи магазина электроники, январь–июнь 2026 (учебные данные)', cols: ['№', 'Дата', 'Регион', 'Менеджер', 'Товар', 'Категория', 'Количество', 'Цена (сом)'], rows };
  DS.salesRev = rows.map(x => x[6] * x[7]);
})();

