  const N = ['Абдыкадыров Нурлан', 'Алымбекова Айгерим', 'Бакиров Эрлан', 'Джумалиева Динара', 'Исаков Бектур', 'Карыпова Жылдыз', 'Мамытов Азамат', 'Насирова Гульнара', 'Омурбеков Талант', 'Рахманова Асель',
    'Садыков Мирлан', 'Токтогулова Айпери', 'Усенов Руслан', 'Шаршеева Назгуль', 'Эсенов Бакыт', 'Ыдырысова Каныкей', 'Жээнбеков Арсен', 'Кадырова Элиза', 'Лукин Андрей', 'Мураталиева Бермет',
    'Нуралиев Тимур', 'Осмонова Салтанат', 'Петрова Ольга', 'Турдубаев Канат'];
