  const r = rng(314);
  const cat = [['T01', 'Ноутбук Lenovo', 'Техника', 52000], ['T02', 'Смартфон Samsung', 'Техника', 24000], ['T03', 'Монитор 24"', 'Техника', 18500], ['T04', 'Принтер лазерный', 'Оргтехника', 14200], ['T05', 'Наушники', 'Аксессуары', 3500],
    ['T06', 'Клавиатура', 'Аксессуары', 1600], ['T07', 'Мышь беспроводная', 'Аксессуары', 900], ['T08', 'Бумага А4 (пачка)', 'Канцтовары', 450], ['T09', 'Флешка 64 ГБ', 'Аксессуары', 750], ['T10', 'Картридж', 'Оргтехника', 3900]];
