DS.opt = { name: 'Ресурсы', title: 'Мебельный цех: расход ресурсов на единицу продукции', cols: ['Ресурс / показатель', 'Стол', 'Шкаф', 'Запас ресурса'],
  rows: [['Древесина (м³)', 2, 1, 100], ['Труд (чел.-ч)', 1, 1, 80], ['Спрос на столы (макс., шт.)', 1, 0, 40], ['Прибыль с единицы (сом)', 3000, 2000, '—']] };

/* ---------- Ответы для самопроверки (считаются из тех же данных) ---------- */
const S = DS.sales.rows;
const ANS = {
  qty: sum(S.map(x => x[6])),
  revenue: sum(DS.salesRev),
  accTen: S.filter(x => x[5] === 'Аксессуары' && x[6] >= 10).length,
  bonus: sum(DS.staff.rows.map(x => x[5] >= 100 && x[3] >= 2 ? x[4] * 0.15 : x[5] >= 90 ? x[4] * 0.05 : 0)),
  vlookup: (() => { const p = Object.fromEntries(DS.catalog.rows.map(c => [c[0], c[3]])); return sum(DS.orders.rows.map(o => (p[o[2]] || 0) * o[3])); })(),
  dirty: DS.dirtyUnique,
  march: sum(S.map((x, i) => x[1].split('.')[1] === '03' ? DS.salesRev[i] : 0)),
  febCons: sum(DS.branches.map(b => sum(b.rows.map(r => r[2])))),
  maxRegion: (() => { const m = {}; S.forEach((x, i) => m[x[2]] = (m[x[2]] || 0) + DS.salesRev[i]); return Math.max(...Object.values(m)); })(),
  techShare: sum(S.map((x, i) => x[5] === 'Техника' ? DS.salesRev[i] : 0)) / sum(DS.salesRev) * 100,
  checkStd: stdevS(DS.checks.rows.map(x => x[1])),
  bin1500: DS.checks.rows.filter(x => x[1] > 1000 && x[1] <= 1500).length,
  planPct: sum(DS.plan.rows.map(x => x[3])) / sum(DS.plan.rows.map(x => x[2])) * 100,
  avgGrowth: (() => { const v = DS.dyn.rows.map(x => x[1]); return Math.pow(v[v.length - 1] / v[0], 1 / (v.length - 1)) * 100; })(),
  correl: correl(DS.adv.rows.map(x => x[1]), DS.adv.rows.map(x => x[2])),
  slope: slope(DS.adv.rows.map(x => x[2]), DS.adv.rows.map(x => x[1])),
  forecast: (() => { const y = DS.monthly.rows.map(x => x[2]), t = DS.monthly.rows.map(x => x[0]); return intercept(y, t) + slope(y, t) * 25; })(),
  bep: 450000 / (1200 - 700),
  lp: (() => { let best = 0; for (let x = 0; x <= 40; x++) for (let y = 0; y <= 100; y++) if (2 * x + y <= 100 && x + y <= 80) best = Math.max(best, 3000 * x + 2000 * y); return best; })(),
  bishAcc: sum(S.map((x, i) => x[2] === 'Бишкек' && x[5] === 'Аксессуары' ? DS.salesRev[i] : 0)),
  avgCheck: mean(DS.salesRev)
};

