function heroChart() {
  const v = DS.monthly.rows.map(r => r[2]), W = 360, H = 200, p = 26, mn = Math.min(...v) - 20, mx = Math.max(...v) + 20;
  const x = i => p + i * (W - 2 * p) / (v.length - 1), y = val => H - p - (val - mn) / (mx - mn) * (H - 2 * p);
  const t = DS.monthly.rows.map(r => r[0]), b = slope(v, t), a = intercept(v, t);
  const line = v.map((val, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(val).toFixed(1)}`).join(' ');
  const bars = v.map((val, i) => `<rect x="${(x(i) - 4).toFixed(1)}" y="${y(val).toFixed(1)}" width="8" height="${(H - p - y(val)).toFixed(1)}" rx="2" fill="var(--accent-soft)"/>`).join('');
  return `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Пример: продажи по месяцам и линейный тренд">
  ${bars}<path d="${line}" fill="none" stroke="var(--accent)" stroke-width="2.2"/>
  <line x1="${x(0)}" y1="${y(a + b)}" x2="${x(23)}" y2="${y(a + b * 24)}" stroke="var(--warn)" stroke-width="2" stroke-dasharray="5 4"/>
  <text x="${p}" y="16" font-size="11" fill="var(--ink-3)" font-family="var(--font)">Продажи по месяцам и тренд ŷ = ${fmt(a, 0)} + ${fmt(b, 1)}·t</text></svg>`;
}

function timelineHTML(pl, compact) {
  let t = 0;
  const bar = `<div class="tl-bar">${pl.map((p, i) => `<span style="flex:${p[0]};background:${PLAN_COLORS[i % 5]}" title="${esc(p[1])}"></span>`).join('')}</div>`;
  const rows = pl.map((p, i) => { const s = t; t += p[0]; return `<div class="tl-row"><div class="tl-time">${s}–${t} мин</div><div class="tl-dot" style="background:${PLAN_COLORS[i % 5]}"></div><div class="tl-text"><b>${esc(p[1])}</b>${compact ? '' : `<span>${esc(p[2])}</span>`}</div></div>`; }).join('');
  return bar + `<div class="timeline">${rows}</div>`;
}

